DROP TABLE IF EXISTS contacts;
CREATE TABLE contacts (contact_id INTEGER PRIMARY KEY, display_name TEXT, city TEXT);
INSERT INTO contacts VALUES (1,'Asha','Rajahmundry'),(2,'Bilal',NULL),(3,'Chitra','Vijayawada');
SELECT display_name,COALESCE(city,'City not provided') AS city_label FROM contacts ORDER BY contact_id;

DROP TABLE IF EXISTS inventory;
CREATE TABLE inventory (item_id INTEGER PRIMARY KEY, item_name TEXT, reorder_level INTEGER);
INSERT INTO inventory VALUES (1,'Cable',10),(2,'Adapter',NULL);
SELECT item_name,IFNULL(reorder_level,0) AS reorder_level FROM inventory ORDER BY item_id;

DROP TABLE IF EXISTS targets;
CREATE TABLE targets (team TEXT, achieved INTEGER, target INTEGER);
INSERT INTO targets VALUES ('East',80,100),('West',30,0);
SELECT team,ROUND(100.0*achieved/NULLIF(target,0),1) AS achievement_percent FROM targets ORDER BY team;

DROP TABLE IF EXISTS people;
CREATE TABLE people (person_id INTEGER PRIMARY KEY, mobile TEXT, email TEXT, office_phone TEXT);
INSERT INTO people VALUES (1,'90001',NULL,'40001'),(2,NULL,'b@example.test','40002'),(3,NULL,NULL,'40003');
SELECT person_id,COALESCE(mobile,email,office_phone,'No contact') AS preferred_contact FROM people ORDER BY person_id;

DROP TABLE IF EXISTS readings;
CREATE TABLE readings (reading_id INTEGER PRIMARY KEY, value INTEGER);
INSERT INTO readings VALUES (1,0),(2,NULL),(3,15);
SELECT reading_id,CASE WHEN value IS NULL THEN 'Not recorded' WHEN value=0 THEN 'Recorded zero' ELSE 'Recorded value' END AS reading_state FROM readings ORDER BY reading_id;

